  border-radius: var(--_card-radius);
  display: block;
  overflow: hidden;
}
.esa-card--header-primary .esa-card__header {
  --_card-header-bg: var(--color-background-brand, #46a758);
  --_card-header-color: var(--color-content-default-knockout, #fcfcfc);
}
.esa-card--header-muted .esa-card__header {
  --_card-header-bg: var(--color-background-elevation-sunken, #f0f0f0);
}
.esa-card__header {
  padding: var(--spacing-400, 1rem) var(--_card-padding);
  background: var(--_card-header-bg);
  color: var(--_card-header-color);
  border-bottom: var(--border-width-default, 1px) solid var(--_card-header-border);
  justify-content: space-between;
  align-items: center;
  min-height: 56px;
  display: flex;
}
.esa-card__header-content {
  align-items: center;
  gap: var(--spacing-300, 0.75rem);
  display: flex;
}
.esa-card__titles {
  gap: var(--spacing-050, 0.125rem);
  flex-direction: column;
  display: flex;
}
.esa-card__title {
  color: inherit;
  margin: 0;
}
.esa-card__actions {
  align-items: center;
  gap: var(--spacing-200, 0.5rem);
  display: flex;
}
.esa-card__body {
  padding: var(--_card-padding);
}
.bcn-ev-staging__item .esa-card {
  overflow: visible;
}
.bcn-ev-targets__item[data-receiving] .esa-card {
  border-color: var(--color-background-brand-muted);
  background: color-mix(in srgb, var(--color-background-brand-muted) 5%, transparent);
}
.bcn-ev-targets__item[data-blocked] .esa-card {
  opacity: 0.45;
}
.bcn-ev-targets__item .esa-card {
  overflow: visible;
}
.bcn-summary {
  gap: var(--spacing-500);
  grid-template-columns: minmax(0, 1.9fr) minmax(0, 1fr);
  align-items: stretch;
  display: grid;
}
@media (width<=860px) {
  .bcn-summary {
    grid-template-columns: 1fr;
  }
}
.bcn-summary > .esa-card {
  height: 100%;
}
.bcn-summary__count {
  min-width: 22px;
  height: 22px;
  padding: 0 var(--spacing-150);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default-secondary);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  font-variant-numeric: tabular-nums;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.bcn-summary__main {
  gap: var(--spacing-400);
  flex-direction: column;
  display: flex;
}
.bcn-summary__bar {
  border-radius: var(--radius-full);
  background: var(--color-background-elevation-sunken);
  height: 14px;
  display: flex;
  overflow: hidden;
}
.bcn-summary__seg {
  background: var(--_c);
  height: 100%;
}
.bcn-summary__legend {
  gap: var(--spacing-200) var(--spacing-500);
  flex-wrap: wrap;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}
.bcn-summary__legend-item {
  align-items: center;
  gap: var(--spacing-200);
  font-size: var(--font-size-150);
  color: var(--color-content-default-secondary);
  display: flex;
}
.bcn-summary__dot {
  border-radius: var(--radius-full);
  background: var(--_c);
  flex-shrink: 0;
  width: 10px;
  height: 10px;
}
.bcn-summary__legend-count {
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  font-variant-numeric: tabular-nums;
}
.bcn-summary__attention {
  flex-direction: column;
  display: flex;
}
.bcn-summary__att-list {
  margin: var(--spacing-400) 0 0;
  padding: var(--spacing-400) 0 0;
  border-top: 1px solid var(--color-border-default-subtle);
  gap: var(--spacing-200);
  flex-direction: column;
  list-style: none;
  display: flex;
}
.bcn-summary__att-row {
  align-items: center;
  gap: var(--spacing-200);
  justify-content: space-between;
  display: flex;
}
.bcn-summary__att-name {
  font-size: var(--font-size-150);
  color: var(--color-content-default);
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
}
.bcn-summary__att-flag {
  align-items: center;
  gap: var(--spacing-100);
  padding: 1px var(--spacing-200);
  border-radius: var(--radius-100);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-utility-danger);
  background: color-mix(in srgb, var(--color-background-utility-danger) 12%, white);
  border: 1px solid color-mix(in srgb, var(--color-background-utility-danger) 26%, white);
  white-space: nowrap;
  flex-shrink: 0;
  display: inline-flex;
}
.bcn-summary__att-more {
  font-size: var(--font-size-100);
  color: var(--bcn-content-muted);
}
