.bcn-cg__host {
  block-size: 38rem;
  inline-size: 100%;
}
.bcn-cg .ag-row {
  cursor: pointer;
}
.bcn-cg .bcn-cg__ident {
  align-items: center;
  gap: var(--spacing-250);
  min-inline-size: 0;
  display: inline-flex;
}
.bcn-cg .bcn-cg__mark {
  border-radius: var(--radius-100);
  background: var(--color-background-elevation-sunken);
  block-size: 24px;
  inline-size: 24px;
  color: var(--_mark);
  flex-shrink: 0;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.bcn-cg .bcn-cg__chip {
  --_tone: var(--bcn-status-not-started, #bdbdbd);
  align-items: center;
  gap: var(--spacing-150);
  padding: 1px var(--spacing-200);
  border-radius: var(--radius-100);
  font-size: 0.875rem;
  line-height: 1.5;
  font-weight: var(--typography-font-weight-medium);
  white-space: nowrap;
  background: color-mix(in srgb, var(--_tone, #bdbdbd) 16%, transparent);
  color: color-mix(in srgb, var(--_tone, #bdbdbd) 70%, var(--color-content-default));
  display: inline-flex;
}
.bcn-cg .bcn-cg__chip:before {
  content: "";
  border-radius: var(--radius-full);
  background: var(--_tone, #bdbdbd);
  width: 7px;
  height: 7px;
}
.bcn-cg .bcn-cg__chip[data-tone="not-started"] {
  --_tone: var(--bcn-status-not-started, #bdbdbd);
}
.bcn-cg .bcn-cg__chip[data-tone="in-progress"] {
  --_tone: var(--color-background-utility-warning, #f59e0b);
}
.bcn-cg .bcn-cg__chip[data-tone="on-hold"] {
  --_tone: var(--bcn-status-on-hold, #656565);
}
.bcn-cg .bcn-cg__chip[data-tone="complete"] {
